use std::fs
use std::process

fn emit(text: string, number: bool, counter: int) -> int {
    let mut c = counter
    if !number {
        print(text)
        return c
    }
    let mut parts: Vec<string> = []
    for p in text.split("\n") {
        parts.push(p)
    }
    let n: int = parts.len() as int
    let mut i = 0
    while i < n {
        let last = i == n - 1
        if last && parts[i as usize] == "" {
            break
        }
        c += 1
        println("${c:>6}\t${parts[i as usize]}")
        i += 1
    }
    c
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in std::env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(t) => { counter = emit(t, number, counter) }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        process::exit(1)
    }
}

